{
  "id": 16,
  "knowledge": "Transaction Chain Risk (TCR)",
  "description": "Evaluates the risk level of a transaction chain",
  "definition": "TCR = (txchainlen \\times 10) + (linkedtxcount \\times 5) + (fraudprob \\times 100) - (profilecomplete \\times 0.5) - (idverifyscore \\times 0.5), \\text{where higher scores indicate higher risk transaction chains.}"
}

{
  "id": 14,
  "knowledge": "Wallet Risk Index (WRI)",
  "description": "Assesses the risk level of cryptocurrency wallets",
  "definition": "WRI = (fraudprob \\times 100) + (wallrisksc \\times 0.5) - \\frac{wallage}{30} + (wallturnrt \\times 10) + \\frac{txvel}{10}, \\text{where higher scores indicate potentially suspicious wallet activity.}"
}

{
  "id": 22,
  "knowledge": "Suspicious Transaction Pattern",
  "description": "Identifies transactions with characteristics suggesting potential illegal activity",
  "definition": "A transaction with TAS > 75, payment in privacy-focused cryptocurrencies (Crypto_B), escrow disabled or minimized (escrowused = 'No' or escrowhrs < 24), and unusual routing complexity (routecomplexity = 'Complex'). These transactions often represent high-risk activities requiring further investigation."
}

{
  "id": 49,
  "knowledge": "Complex Money Laundering Operation",
  "description": "Identifies sophisticated financial obfuscation schemes",
  "definition": "A transaction network with MFC > 90, displaying Money Laundering Indicator characteristics, high TCR scores (TCR > 180), and 'High' money laundering risk classification as defined in the money laundering risk system. These operations represent the most sophisticated financial obfuscation attempts requiring specialized financial investigation approaches."
}

{
  "id": 39,
  "knowledge": "Money Flow Complexity (MFC)",
  "description": "Quantifies the complexity of money flows in transaction chains",
  "definition": "MFC = (txchainlen \\times 5) + (linkedtxcount \\times 3) + (moneyrisk_numeric \\times 15) + (TCR \\times 0.2) - (profilecomplete \\times 10), \\text{where moneyrisk_numeric maps Low=1, Medium=2, High=3, Unknown=2 according to the money laundering risk classification, and higher scores indicate more complex money flows.}"
}

{
  "id": 12,
  "knowledge": "Transaction Anomaly Score (TAS)",
  "description": "Detects unusual transactions based on multiple variables",
  "definition": "TAS = \\frac{payamtusd}{1000} \\times \\frac{txfinishhrs}{24} \\times \\left(1 + \\frac{escrowhrs}{100}\\right) \\times \\left(1 - \\frac{esccomprate}{100}\\right), \\text{where esccomprate is from the associated market, and higher scores indicate more suspicious transactions.}"
}
